$("importCuratedAssets").addEventListener("click",async()=>{const b=$("importCuratedAssets"),s=$("curatedAssetStatus");b.disabled=true;s.className="status";s.textContent="Checking curated contracts on their respective networks…";try{const result=await api("/api/admin/supported-assets/curated",{method:"POST",body:"{}"});const failed=(result.rejected||[]).length;s.textContent=result.activeTotal+" of "+result.catalogTotal+" curated tokens are active in the registry. "+result.verifiedThisRun+" passed verification on this attempt."+(failed?" "+failed+" need another check: "+result.rejected.map(x=>x.network+" "+x.symbol+" ("+x.reason+")").join("; "):" All catalog entries passed on-chain checks.")+" Previously verified tokens remain registered. Review the supported-assets list below.";await load()}catch(e){s.className="status error";s.textContent=e.message}finally{b.disabled=false}});

$("policyNetwork").addEventListener("change",renderPolicyChoices);$("policyAssetChoices").addEventListener("change",renderPolicyChoices);$("policyForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget;const b=Object.fromEntries(new FormData(form));const asset=supportedAssets.find(x=>x.id===b.assetId&&x.network===b.network&&x.isActive);try{if(!asset)throw new Error("Choose a verified supported token for the selected network.");const maxAmountRaw=parseHumanAmount(b.maxAmountHuman,Number(asset.decimals));if(b.automaticPriorityEnabled!=="on"&&b.adminInitiatedEnabled!=="on")throw new Error("Select at least one recovery mode.");await api("/api/admin/recovery-destination-policies/"+encodeURIComponent(b.network)+"/"+encodeURIComponent(asset.id),{method:"PUT",body:JSON.stringify({destinationId:b.destinationId,maxAmountRaw,expiresInSeconds:Number(b.expiresInSeconds),automaticPriorityEnabled:b.automaticPriorityEnabled==="on",adminInitiatedEnabled:b.adminInitiatedEnabled==="on"})});$("policyStatus").className="status";$("policyStatus").textContent="Policy saved for "+asset.symbol+". The owner must still approve the exact on-chain authorization.";form.reset();renderPolicyChoices();await load()}catch(err){$("policyStatus").className="status error";$("policyStatus").textContent=err.message}});
